def merge_intervals(intervals):
    if not intervals:
        return []
    sorted_intervals = [list(iv) for iv in intervals]
    sorted_intervals.sort(key=lambda x: x[0])
    merged = []
    for start, end in sorted_intervals:
        if not merged or start > merged[-1][1]:
            merged.append([start, end])
        else:
            if end > merged[-1][1]:
                merged[-1][1] = end
    return merged

import heapq

def toposort(nodes, edges):
    nodes = list(nodes)
    edges = list(edges)
    indegree = {n: 0 for n in nodes}
    adj = {n: set() for n in nodes}

    for src, dst in edges:
        if src == dst:
            raise ValueError("self loop detected")
        if dst not in adj[src]:
            adj[src].add(dst)
            indegree[dst] += 1

    heap = [n for n in nodes if indegree[n] == 0]
    heapq.heapify(heap)
    result = []

    while heap:
        n = heapq.heappop(heap)
        result.append(n)
        for nb in adj[n]:
            indegree[nb] -= 1
            if indegree[nb] == 0:
                heapq.heappush(heap, nb)

    if len(result) != len(nodes):
        raise ValueError("cycle detected")
    return result

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError
    batches = []
    cur = []
    cur_sum = 0
    for name, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError
        if cur_sum + weight > limit:
            batches.append(cur)
            cur = [name]
            cur_sum = weight
        else:
            cur.append(name)
            cur_sum += weight
    if cur:
        batches.append(cur)
    return batches

import re

_key_re = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')

def parse_env(text):
    env = {}
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith('#'):
            continue
        if '=' not in line:
            raise ValueError(f"Invalid line: {raw!r}")
        key, value = line.split('=', 1)
        key = key.strip()
        value = value.strip()
        if not _key_re.match(key):
            raise ValueError(f"Invalid key: {key!r}")
        if len(value) >= 2 and value[0] == value[-1] and value[0] in ("'", '"'):
            value = value[1:-1]
        env[key] = value
    return env

def parse_sse(chunks):
    raw = b"".join(chunks)
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        text = raw.decode("utf-8", errors="replace")

    events = []
    parts = []
    for line in text.splitlines():
        if line == "":
            if parts:
                data = "\n".join(parts)
                if data == "[DONE]":
                    break
                if data:
                    events.append(data)
                parts = []
            continue

        if line.startswith(":"):
            continue
        if line.startswith("data:"):
            rest = line[5:]
            if rest.startswith(" "):
                rest = rest[1:]
            parts.append(rest)
        # other fields ignored

    return events

def retry_delay(attempt, base, cap):
    if attempt < 0 or base < 0 or cap < 0:
        raise ValueError("arguments must be non-negative")
    if base == 0:
        return 0.0
    if cap == 0:
        return 0.0
    if base >= cap:
        return float(cap)

    import math
    # avoid building 2**attempt for huge attempt
    # base * 2**attempt > cap  <=>  attempt > log2(cap/base)
    # log2 is safe for finite positive numbers
    try:
        ratio = cap / base
    except ZeroDivisionError:
        return 0.0

    # if attempt is already beyond the range where a double can represent,
    # 2**attempt will certainly exceed any finite cap/base
    if attempt > 1024:
        return float(cap)

    if attempt > math.log2(ratio):
        return float(cap)

    # now attempt is small enough that the power is representable
    return float(base * (2 ** attempt))
